 function installKnowledge(){
  window.NOOR_KNOWLEDGE_QUESTIONS=KB;
  document.addEventListener('click',e=>{const btn=e.target.closest('[data-knowledge-bank]'); if(!btn)return; setTimeout(()=>{
   const root=$('#knowledgeBank'); if(!root)return; root.classList.remove('hidden'); $('#ruqyahHub')?.classList.add('hidden');
   renderKB(root);
  },20)},true);
 }
 function renderKB(root){
  const unique=[]; const seen=new Set(); for(const x of KB){if(seen.has(x.canonicalId))continue;seen.add(x.canonicalId);unique.push(x)}
  const cats=['الكل',...new Set(unique.map(x=>x.category))];
  root.innerHTML=`<div class="bundle-head"><button class="btn" id="kbLocalBack">← أقسام الرقية</button><div><span class="eyebrow">بنك المعرفة</span><h2>الأسئلة والأجوبة</h2><p>${unique.length} سؤالًا أصليًا موثقًا، يعمل محليًا ودون خادم.</p></div></div><div class="kb-tools"><input id="kbLocalSearch" type="search" placeholder="اكتب سؤالك..."><p id="kbLocalCount"></p></div><div class="kb-cats">${cats.map(c=>`<button data-lcat="${esc(c)}" class="${c==='الكل'?'active':''}">${esc(c)}</button>`).join('')}</div><div id="kbLocalList" class="kb-list"></div>`;
  let cat='الكل'; const draw=()=>{const q=($('#kbLocalSearch').value||'').trim(); const rows=unique.filter(x=>(cat==='الكل'||x.category===cat)&&(!q||x.question.includes(q)||x.answer.includes(q)||String(x.keywords||'').includes(q))); $('#kbLocalCount').textContent=rows.length+' نتيجة'; $('#kbLocalList').innerHTML=rows.map(x=>`<article class="kb-card"><header><span>${esc(x.category)}</span></header><h3>${esc(x.question.replace(/^(أريد معرفة: |ما الإجابة عن سؤال: |اشرح لي: |هل يمكن توضيح: |سؤال شائع: |ما الصحيح في: |ما الحكم أو التوجيه في: |كيف أفهم: |أبحث عن جواب: )/,''))}</h3><p>${esc(x.answer)}</p><footer><small>المصدر: ${esc(x.source)}</small></footer></article>`).join('')||'<div class="search-empty"><p>لا توجد نتيجة.</p></div>'};
  $('#kbLocalSearch').oninput=draw; $$('[data-lcat]',root).forEach(b=>b.onclick=()=>{cat=b.dataset.lcat;$$('[data-lcat]',root).forEach(x=>x.classList.toggle('active',x===b));draw()}); $('#kbLocalBack').onclick=()=>{root.classList.add('hidden');$('#ruqyahHub')?.classList.remove('hidden')}; draw();
 }
 function rebuildAssessment(){const sec=$('#assessment'); if(!sec)return; sec.innerHTML=`<div class="pro-assess-shell"><header><span>تقييم توعوي غير تشخيصي</span><h1>افهم الأعراض بهدوء ومسؤولية</h1><p>هذا التقييم لا يثبت عينًا أو سحرًا أو مسًا. هدفه تنظيم الملاحظات وتحديد متى تحتاج إلى طبيب أو مختص.</p></header><div class="pro-assess-alert"><b>ابدأ بالأسباب الطبية والنفسية</b><p>أي ألم شديد، إغماء، صعوبة تنفس، أفكار إيذاء النفس، تشنجات، نزيف، أو تدهور سريع يحتاج رعاية عاجلة.</p></div><div class="pro-assess-grid"><button data-pro-assess="physical"><span>🩺</span><h3>أعراض جسدية</h3><p>الألم، الصداع، الإرهاق، الجهاز الهضمي والنوم.</p></button><button data-pro-assess="mental"><span>🧠</span><h3>نفسية ومزاجية</h3><p>القلق، الوسواس، الحزن، الخوف والتوتر.</p></button><button data-pro-assess="sleep"><span>🌙</span><h3>النوم والأحلام</h3><p>الأرق والكوابيس والاستيقاظ المتكرر دون اعتبارها دليلًا غيبيًا.</p></button><button data-pro-assess="urgent"><span>🚑</span><h3>علامات طوارئ</h3><p>متى يجب التوجه فورًا إلى الرعاية الطبية.</p></button></div><div id="proAssessPanel"></div></div>`;
 const qs={physical:['هل الأعراض مستمرة أكثر من أسبوعين؟','هل تؤثر في العمل أو الطعام أو الحركة؟','هل يوجد ألم شديد أو حرارة أو فقدان وزن غير مفسر؟'],mental:['هل القلق أو الحزن يؤثران في حياتك اليومية؟','هل توجد نوبات هلع أو وساوس متكررة؟','هل فكرت في إيذاء نفسك أو غيرك؟'],sleep:['هل تنام أقل من 6 ساعات غالبًا؟','هل تستيقظ مرهقًا بصورة مستمرة؟','هل تستخدم منبهات أو شاشة قبل النوم بكثرة؟'],urgent:['هل توجد صعوبة تنفس أو ألم صدر؟','هل حدث إغماء أو تشنج؟','هل توجد أفكار إيذاء النفس؟']};
 $$('[data-pro-assess]',sec).forEach(b=>b.onclick=()=>{const type=b.dataset.proAssess; const panel=$('#proAssessPanel'); panel.innerHTML=`<article class="pro-assess-form"><h2>${b.querySelector('h3').textContent}</h2>${qs[type].map((q,i)=>`<label><span>${q}</span><select data-pa><option value="0">لا</option><option value="1">أحيانًا</option><option value="2">نعم</option></select></label>`).join('')}<button class="btn primary" id="paResult">عرض التوجيه</button><div id="paOut"></div></article>`; $('#paResult').onclick=()=>{const vals=$$('[data-pa]',panel).map(x=>+x.value),sum=vals.reduce((a,b)=>a+b,0); let msg=type==='urgent'&&sum?'توجد علامة تستحق تقييمًا طبيًا عاجلًا الآن. لا تنتظر الرقية أو التقييم الإلكتروني.':sum>=4?'الأعراض متكررة ومؤثرة؛ احجز موعدًا مع طبيب أو مختص، واستمر في الأذكار والرقية كعبادة مساندة لا كبديل للعلاج.':sum>=2?'راقب الأعراض وسجل توقيتها ومحفزاتها، وراجع مختصًا إن استمرت أو زادت.':'لا تظهر من إجاباتك علامة قوية، لكن أي عرض مقلق أو مستمر يستحق الفحص.'; $('#paOut').innerHTML=`<div class="pro-assess-result">${msg}</div>`}; panel.scrollIntoView({behavior:'smooth'})})
 }
 function rebuildDreams(){const sec=$('#dreams'); if(!sec)return; const cats=['الكل',...new Set(DREAMS.map(x=>x[1]))]; sec.innerHTML=`<div class="dream-app"><header><span>تعبير الرؤى</span><h1>دليل رموز جاهز داخل التطبيق</h1><p>معانٍ استئناسية عامة وليست أحكامًا قطعية. الرؤيا تتأثر بحال الرائي والسياق، ولا يُبنى عليها حكم شرعي أو قرار مصيري.</p></header><div class="dream-notice"><b>قبل البحث</b><p>قد يكون الحلم من حديث النفس أو أثر التوتر والطعام والنوم. لا تُفسَّر الأحلام المخيفة على أنها سحر أو مس.</p></div><div class="dream-search"><input id="dreamLocalSearch" type="search" placeholder="ابحث: ماء، أسد، سفر، ذهب..."><div>${cats.map(c=>`<button data-dcat="${c}" class="${c==='الكل'?'active':''}">${c}</button>`).join('')}</div></div><div id="dreamLocalList" class="dream-symbol-grid"></div></div>`; let cat='الكل'; const draw=()=>{const q=$('#dreamLocalSearch').value.trim(); const rows=DREAMS.filter(x=>(cat==='الكل'||x[1]===cat)&&(!q||x[0].includes(q)||x[2].includes(q))); $('#dreamLocalList').innerHTML=rows.map(x=>`<article><small>${x[1]}</small><h3>${x[0]}</h3><p>${x[2]}</p><div>المعنى استئناسي وليس حكمًا قطعيًا.</div></article>`).join('')}; $('#dreamLocalSearch').oninput=draw; $$('[data-dcat]',sec).forEach(b=>b.onclick=()=>{cat=b.dataset.dcat;$$('[data-dcat]',sec).forEach(x=>x.classList.toggle('active',x===b));draw()}); draw()}
 function enhanceQuran(){const sec=$('#quran'); if(!sec)return; sec.classList.add('mushaf-page-mode'); const title=sec.querySelector('.section-title'); if(title) title.innerHTML='<div><h2>المصحف الشريف</h2><p class="muted">اختر السورة لتظهر في صفحة قراءة تشبه المصحف، واضغط على الآية لإظهار التفسير الميسر.</p></div>';
  const obs=new MutationObserver(()=>{const card=$('#quranReader .quran-tafsir-card'); if(card) card.classList.add('mushaf-paper')}); obs.observe($('#quranReader'),{childList:true,subtree:true});
 }
 document.addEventListener('DOMContentLoaded',()=>{fixRuqyahCards();installBasicReading();installKnowledge();rebuildAssessment();rebuildDreams();enhanceQuran()});
